<script setup>
import { onMounted, ref } from 'vue'; import Button from 'primevue/button'; import StatusTag from '../../components/StatusTag.vue'; import LoadingState from '../../components/LoadingState.vue'; import EmptyState from '../../components/EmptyState.vue'; import api,{errorMessage} from '../../services/api'; import {formatDate} from '../../utils/status'
const notifications=ref([]),loading=ref(true),error=ref('');const load=async()=>{loading.value=true;try{notifications.value=(await api.get('/notifications/my')).data}catch(e){error.value=errorMessage(e)}finally{loading.value=false}};const read=async(n)=>{if(!n.read){await api.patch(`/notifications/${n.id}/read`);n.read=true}};const all=async()=>{await api.patch('/notifications/read-all');notifications.value.forEach(n=>n.read=true)};onMounted(load)
</script>
<template><div class="page-heading"><div><h1>Thông báo</h1><p>Cập nhật mới nhất liên quan tới cộng đồng của bạn.</p></div><Button label="Đọc tất cả" text icon="pi pi-check-double" :disabled="!notifications.some(n=>!n.read)" @click="all" /></div><div class="content-card"><LoadingState v-if="loading" /><div v-else-if="error" class="error-panel">{{error}}</div><EmptyState v-else-if="!notifications.length" title="Chưa có thông báo" /><div v-else class="notification-list"><button v-for="n in notifications" :key="n.id" class="notification-item" :class="{unread:!n.read}" @click="read(n)"><span class="notification-dot" /><span><div class="visitor-top"><strong>{{n.title}}</strong><StatusTag :value="n.type" /></div><small>{{n.message}}</small><time>{{formatDate(n.createdAt)}}</time></span></button></div></div></template>
